 // Build DOM nodes rather than interpreting HTML from user content. This intentionally covers
 // common Discord markdown; unsupported syntax remains visible instead of being executed.
 // Only construct a fixed Discord CDN URL from validated numeric IDs. The source
 // document keeps its original emoji syntax; an unavailable image falls back to it.
 function customEmoji(token){
  const match=/^<(a?):([A-Za-z0-9_]{2,32}):(\d{17,20})>$/.exec(token);
  if(!match)return null;
  const image=el('img',{className:'ms-custom-emoji',alt:`:${match[2]}:`,title:`:${match[2]}:`});
  image.referrerPolicy='no-referrer';image.addEventListener('error',()=>image.replaceWith(document.createTextNode(token)),{once:true});
  image.src=`https://cdn.discordapp.com/emojis/${match[3]}.${match[1]?'gif':'png'}?size=48`;
  return image;
 }
 function previewButton(item){
  const node=el('button',{type:'button',disabled:item.disabled===true,'data-style':item.style});
  if(item.emoji){node.append(customEmoji(item.emoji)||document.createTextNode(item.emoji),document.createTextNode(' '));}
  node.append(document.createTextNode(item.label||tr('Tombol','Button')));return node;
 }
