   if(selected().block!==block || block.content!==oldContent){aiStatus.textContent=tr('Komponen berubah; pilih lagi sebelum menerapkan.','The component changed; select it again before applying.');return;}block.content=text;state.status=tr('Draf diterapkan; tinjau preview sebelum menyimpan atau mengirim.','Draft applied; review the preview before saving or sending.');drawEditor(root);aiStatus.textContent=tr('Draf diterapkan ke komponen terpilih.','Draft applied to the selected component.');
