  const importText=async(text)=>{try{if(new Blob([text]).size>1024*1024)throw Error(tr('JSON maksimal 1 MB.','JSON maximum 1 MB.'));const parsed=JSON.parse(text);let doc,status;if(parsed?.version===1&&Array.isArray(parsed.containers)&&validOrder(parsed)){const result=await request('/validate-import',{method:'POST',body:{document:parsed}});doc=result.document;status=tr('JSON Message Studio divalidasi dan dimuat.','Message Studio JSON validated and loaded.');}else{const result=await request('/import-discord',{method:'POST',body:{message:parsed}});doc=result.document;status=[tr('JSON Discord dimuat.','Discord JSON loaded.'),...(result.warnings||[])].join(' ');}if(!(await (window.ZentixDialog ? window.ZentixDialog.confirm(tr('Ganti dokumen editor dengan JSON impor? Perubahan yang belum disimpan akan hilang.','Replace the editor document with imported JSON? Unsaved changes will be lost.')) : Promise.resolve(window.confirm(tr('Ganti dokumen editor dengan JSON impor? Perubahan yang belum disimpan akan hilang.','Replace the editor document with imported JSON? Unsaved changes will be lost.'))))))return;state.doc=doc;state.selection=firstSelection(state.doc);state.templateId=null;state.messageId=null;state.templateName='';state.uploads.clear();state.status=status;drawEditor(root);}catch(error){setStatus(root,error instanceof SyntaxError?tr('JSON tidak valid.','Invalid JSON.'):error.message||tr('JSON tidak cocok dengan format yang didukung.','JSON does not match a supported format.'));}};
