 function bind(root,tab,notify){if(tab==='library'){reload(root,'library').catch(error=>{const box=$('#msTemplates',root);if(box)box.textContent=error.message;});return;}reload(root,'editor').then(()=>bindEditor(root,notify)).catch(error=>{const status=$('#msStatus',root);if(status)status.textContent=error.message;});}
